namespace ghidra.app.plugin.core.function;



using docking.action;
using ghidra.app.context;
using ghidra.app.context;
using ghidra.program.model.data;
using ghidra.program.util;
using ghidra.program.util;
using ghidra.util;

/**
 * Base class for actions to create data types
 */
class DataAction : ListingContextAction {

	private string group;
	protected DataType dataType;
	protected FunctionPlugin plugin;

	public DataAction(DataType dataType, FunctionPlugin plugin) : this("Define " + dataType.getDisplayName(), "Function", dataType, plugin)
    {
		setHelpLocation(new HelpLocation(plugin.getName(), "DataType"));
	}

	public DataAction(string name, string group, DataType dataType, FunctionPlugin plugin) : base(name, plugin.getName(), KeyBindingType.SHARED)
    {
		this.group = group;
		this.plugin = plugin;
		this.dataType = dataType;

		setPopupMenu(plugin.getDataActionMenuName(null), true);
		setHelpLocation(new HelpLocation(plugin.getName(), "DataType"));

		initKeyStroke(getDefaultKeyStroke());
	}

	protected KeyStroke getDefaultKeyStroke() {
		return null; // we have no default, but our subclasses may
	}

	protected void initKeyStroke(KeyStroke keyStroke) {
		if (keyStroke == null) {
			return;
		}

		setKeyBindingData(new KeyBindingData(keyStroke));
	}

	void setPopupMenu(string name, bool isSignatureAction) {
		setPopupMenuData(new MenuData(
			new string[] { FunctionPlugin.SET_DATA_TYPE_PULLRIGHT, dataType.getDisplayName() },
			group));
	}

	/* @Override */
	public void dispose() {
		dataType = null;
		plugin = null;
		base.dispose();
	}

	/* @Override */
	protected bool isEnabledForContext(ListingActionContext context) {
		if (context.hasSelection() || context.getAddress() == null) {
			return false;
		}
		ProgramLocation location = context.getLocation();
		if (plugin.isValidDataLocation(location)) {
			setPopupMenu(plugin.getDataActionMenuName(location), true);
			return true;
		}
		if (location is VariableLocation) {
			setPopupMenu(plugin.getDataActionMenuName(location), false);
			return true;
		}
		return false;
	}

	/* @Override */
	public void actionPerformed(ListingActionContext context) {
		plugin.createData(dataType, context, true, true);
	}
}
